import React, { Component } from "react";
import { useLocation, Route, Switch } from "react-router-dom";

// ลบ AdminNavbar ออกแล้ว
import Footer from "components/Footer/Footer";
import Sidebar from "components/Sidebar/Sidebar";

import routes from "routes.js";
// เปลี่ยนเป็นรูปที่คุณต้องการ (my-background1.jpg)
import sidebarImage from "assets/img/my-background1.jpg";

function Admin() {
  const [image, setImage] = React.useState(sidebarImage);
  const [color, setColor] = React.useState("black");
  const [hasImage, setHasImage] = React.useState(true);
  const location = useLocation();
  const mainPanel = React.useRef(null);
  const [overlayOpen, setOverlayOpen] = React.useState(false);
  
  const getRoutes = (routes) => {
    return routes.map((prop, key) => {
      if (prop.layout === "/admin") {
        return (
          <Route
            path={prop.layout + prop.path}
            render={(props) => <prop.component {...props} />}
            key={key}
          />
        );
      } else {
        return null;
      }
    });
  };

  React.useEffect(() => {
    document.documentElement.scrollTop = 0;
    document.scrollingElement.scrollTop = 0;
    mainPanel.current.scrollTop = 0;
    if (
      window.innerWidth < 993 &&
      document.documentElement.className.indexOf("nav-open") !== -1
    ) {
      document.documentElement.classList.toggle("nav-open");
      var element = document.getElementById("bodyClick");
      if (element) element.parentNode.removeChild(element);
    }
  }, [location]);

  return (
    <>
      <div className="wrapper">
        {/* ส่งรูปภาพที่ตั้งไว้ไปยัง Sidebar */}
        <Sidebar color={color} image={hasImage ? image : ""} routes={routes} />
        <div className="main-panel" ref={mainPanel}>
          {/* ลบ <AdminNavbar /> ออกจากตรงนี้แล้ว */}
          <div className="content">
            <Switch>{getRoutes(routes)}</Switch>
          </div>
          <Footer />
        </div>
      </div>
      {/* 🔘 Global Floating Button */}
      <button
        onClick={() => setOverlayOpen(!overlayOpen)}
        style={{
          position: "fixed",
          top: "20px",
          right: "20px",
          zIndex: 4000,
          borderRadius: "50%",
          width: "48px",
          height: "48px",
          border: "none",
          background: "#1DC7EA",
          color: "#fff",
          fontSize: "22px",
          cursor: "pointer",
        }}
      >
      </button>
      {/* 📋 Global Overlay Panel */}
      <div
        style={{
          position: "fixed",
          top: 0,
          right: overlayOpen ? 0 : "-320px",
          width: "320px",
          height: "100vh",
          background: "#fff",
          boxShadow: "-4px 0 12px rgba(0,0,0,0.2)",
          transition: "0.3s ease",
          zIndex: 3500,
          padding: "20px",
          overflowY: "auto",
        }}
      >
        <h4>📊 Control Panel</h4>
        <hr />

        <p>ใช้แสดงข้อมูลเสริม</p>
        <ul>
          <li>🚌 สายรถ</li>
          <li>📍 ป้ายรถ</li>
          <li>👥 ความหนาแน่น</li>
        </ul>
      </div>
      {/* ลบ FixedPlugin ออกถาวรแล้ว */}
    </>
  );
}

export default Admin;
